set -euo pipefail
db_user=$(docker exec postgres printenv POSTGRES_USER)
docker exec -i postgres psql -X -qAt -v ON_ERROR_STOP=1 -U "$db_user" -d coaching_db <<'SQL'
SELECT 'edition',"Code","SubjectName","AcademicYearStart","AcademicYearEnd",count(*) OVER() FROM coaching.official_curriculum_editions;
SELECT 'unique-duration',count(*),sum(e."LearningMinutes"+e."PracticeMinutes"+e."CheckMinutes") FROM coaching.study_catalog_outcomes o JOIN coaching.outcome_duration_estimates e ON e."OutcomeId"=o."Id" AND e."IsPublished" AND NOT EXISTS(SELECT 1 FROM coaching.outcome_duration_estimates n WHERE n."OutcomeId"=e."OutcomeId" AND n."IsPublished" AND n."Number">e."Number") WHERE NOT o."IsArchived";
SELECT 'topic-order',u."Name",u."DisplayOrder",t."Name",t."DisplayOrder" FROM coaching.study_catalog_topics t JOIN coaching.study_catalog_units u ON u."Id"=t."UnitId" JOIN coaching.study_catalog_lessons l ON l."Id"=t."LessonId" WHERE l."Name"='Matematik' AND l."ExamCode"='LGS' ORDER BY u."DisplayOrder",t."DisplayOrder",t."Id";
SELECT 'outcome-order',"Code","DisplayOrder" FROM coaching.study_catalog_outcomes ORDER BY "DisplayOrder","Code" LIMIT 8;
SELECT 'all-generated-inside-weekly-slots',NOT EXISTS(SELECT 1 FROM coaching.study_plan_tasks t JOIN coaching.study_plan_revisions r ON r."Id"=t."RevisionId" JOIN coaching.study_weekly_drafts d ON d."StudentId"=r."StudentId" WHERE r."WeeklySource" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d."SlotsJson") s WHERE (s->>'Day')::int=extract(dow FROM t."PlannedDate")::int AND (s->>'LessonId')::uuid=t."WeeklyLessonId" AND t."PlannedStartMinute">=(s->>'StartMinute')::int AND t."PlannedStartMinute"+t."PlannedMinutes"<=(s->>'StartMinute')::int+(s->>'DurationMinutes')::int));
SELECT 'weekly-source-current',r."WeeklySource"->>'DraftVersion'=d."Version"::text,'source-context-current',r."WeeklySource"->>'LearningContextVersion'=c."Version"::text FROM coaching.study_plan_revisions r JOIN coaching.study_weekly_drafts d ON d."StudentId"=r."StudentId" JOIN coaching.student_learning_contexts c ON c."StudentUserId"=r."StudentId" WHERE r."WeeklySource" IS NOT NULL;
SQL
